using UnityEngine;
using UnityEngine.SceneManagement;
using System.Linq;
using TMPro;

public sealed class GridShiftWardrobe:MonoBehaviour {
 public static void Install(Scene scene){if(scene.name!="Office"||scene.GetRootGameObjects().Any(g=>g.name=="Office wardrobe"))return;var player=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).FirstOrDefault(p=>p.gameObject.scene==scene);if(player==null)return;Vector3 at=Vector3.zero;Quaternion rotation=Quaternion.identity;bool found=false;foreach(float radius in new[]{2.6f,3.4f,4.2f}){for(int i=0;i<12;i++){var point=player.transform.position+Quaternion.Euler(0,i*30,0)*Vector3.forward*radius;if(!Physics.Raycast(point+Vector3.up*2,Vector3.down,out var floor,4,~((1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||floor.normal.y<.9f||Mathf.Abs(floor.point.y-player.transform.position.y)>.6f)continue;point.y=floor.point.y;rotation=Quaternion.LookRotation(Vector3.ProjectOnPlane(player.transform.position-point,Vector3.up));if(Physics.OverlapBox(point+Vector3.up*1.15f,new Vector3(.68f,1.05f,.32f),rotation,~((1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore).Any(c=>!c.transform.IsChildOf(player.transform)))continue;at=point;found=true;break;}if(found)break;}if(!found){Debug.LogWarning("Guarda-roupa: não há espaço livre próximo à entrada do Office.");return;}var go=new GameObject("Office wardrobe");SceneManager.MoveGameObjectToScene(go,scene);go.transform.SetPositionAndRotation(at,rotation);go.AddComponent<GridShiftWardrobe>();var config=Resources.Load<GridShiftActiveConfig>("GridShiftActiveConfig");Part(go.transform,"Wardrobe body",new Vector3(0,1.1f,0),new Vector3(1.2f,2.2f,.5f),config.structureMaterial,true);foreach(float side in new[]{-.3f,.3f}){Part(go.transform,"Wardrobe door",new Vector3(side,1.1f,.27f),new Vector3(.57f,2.1f,.035f),config.floorMaterial,false);Part(go.transform,"Wardrobe handle",new Vector3(side*.35f,1.1f,.31f),new Vector3(.04f,.3f,.04f),config.accentMaterial,false);}var label=new GameObject("Wardrobe label",typeof(TextMeshPro));label.transform.SetParent(go.transform,false);label.transform.localPosition=new Vector3(0,2.5f,0);label.transform.localRotation=Quaternion.Euler(0,180,0);var text=label.GetComponent<TextMeshPro>();text.text="GUARDA-ROUPA\nPERSONAGEM";text.fontSize=1.3f;text.alignment=TextAlignmentOptions.Center;text.rectTransform.sizeDelta=new Vector2(2,.6f);var action=GridShiftWorldAction.Create(go.transform,"Trocar roupa / aparência",new Vector3(0,0,.7f),p=>{GridShiftCharacterEditor.Open(GridShiftCharacter.Current,d=>{GridShiftCharacter.Commit(d);DeliveryManager.Instance.GetComponent<DeliveryPersistence>().Save();DeliveryManager.Instance.Notify("Personagem e roupa atualizados neste save.");});return true;});action.focusOffset=Vector3.up*1.1f;action.focusSize=new Vector3(1.3f,2,.5f);}
 static void Part(Transform parent,string name,Vector3 at,Vector3 size,Material material,bool solid){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=at;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=material;g.GetComponent<Collider>().enabled=solid;}
}
